/// <summary>
/// Provides calculation logic for packing amounts and charges related to waste management.
/// </summary>
public class AVARUMDSDCalculationManager
{
}

Method.Source:
/// <summary>
/// Calculates the packing amount for a given item and updates the sales line with the calculated amount.
/// </summary>
/// <param name="_qty">Quantity to calculate for.</param>
/// <param name="_itemId">Item ID for calculation.</param>
/// <param name="_configId">Item configuration ID.</param>
/// <param name="_dsdSalesLine">Sales line to update.</param>
/// <param name="_itemIdMother">Mother item ID for BOM calculation.</param>
/// <param name="_date">Date for calculation (default is today).</param>
static SalesPrice calcPackingAmount
(
    InventQty _qty,
    ItemId _itemId,
    EcoResItemConfigurationName _configId,
    SalesLine _dsdSalesLine,
    ItemId _itemIdMother,
    utcDateTime _date = DateTimeUtil::utcNow()
)
{
    InventDim inventDim;
    EcoResDistinctProductVariant distinctProductVariant;
    InventDimCombination inventDimCombination;
    InventTable inventTable;
    BOMVersion bomVersion;
    BOMTable bomTable;
    BOM bom;
    Real basisP;
    Real basis;
    InventQty inventQty;
    SalesLineAmount actAmount;
    UnitOfMeasureRecId unitFromRecid;
    UnitOfMeasureRecId unittoRecid;
    UnitOfMeasureRecId unitInventrecid;
    UnitIdbase unitFrom;
    UnitIdbase unitTo;
    UnitIdbase unitInvent;
    CurrencyCode companyCurrencyCode;
    CurrencyExchangeHelper currencyExchangeHelper;
    AVARUMDSDCodeTable codes;
    SalesPrice rc=0;

    companyCurrencyCode = Ledger::accountingCurrency(CompanyInfo::current());
    InventDim locInventDim;
    locInventDim.configId=_configId;
    inventDimCombination=InventDimCombination::findByInventDim(_itemId, locInventDim);
    distinctProductVariant=EcoResDistinctProductVariant::find(inventDimCombination.DistinctProductVariant);

    if (distinctProductVariant.AVARUMDSDUsage)
    {
        inventTable = InventTable::find(_itemId);

        if (distinctProductVariant.AVARUMDSDPackaging)
        {
            basisP = _dsdSalesLine.SalesQty * _qty;

            if (distinctProductVariant.AVARUMDSDWeightGroupId)
            {
                basis = basisP * distinctProductVariant.AVARUMDSDWeight; //Old: inventTable.NetWeight;

                // Weight price is stored per kg, DSD entry always in inventory unit
                unitInvent = InventTableModule::find(AVARUMDSDManager::getDefaultDSDItemId(true), ModuleInventPurchSales::Invent).unitId; // GP item
                unitInventRecid = UnitOfMeasure::findBySymbol(unitInvent).RecId;
                unitFrom = InventTableModule::find(_itemIdMother, ModuleInventPurchSales::Invent).unitId;               // CreateSalesline item
                unitFromRecid = UnitOfMeasure::findBySymbol(unitFrom).RecId;

                if (unitFrom != unitInvent)
                {
                    if (UnitOfMeasureConverter::canBeConverted(unitFromRecid, unitInventRecid, InventTable::find(_itemIdMother).RecId))
                    {
                        inventQty = EcoResProductUnitConverter::convertForReleasedProduct
                        (
                            _itemIdMother,
                            '',
                            basis,
                            unitFromRecid,
                            unitInventRecid
                        );

                        basis = EcoResProductUnitConverter::convertForReleasedProduct
                        (
                            _itemIdMother,
                            '',
                            inventQty,
                            unitInventRecid,
                            unittoRecid
                        );
                    }
                }

                codes = AVARUMDSDCodeTable::find(AVARUMDSDClass::Weight, distinctProductVariant.AVARUMDSDWeightGroupId, _date);
                //currencyExchangeHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::current(), systemDateGet());

                actAmount = (basis * codes.FeePerWeight);
                //old: actAmount = currencyExchangeHelper.calculateCurrencyToCurrency(_dsdSalesLine.CurrencyCode, companyCurrencyCode,actAmount,true);
                //_dsdSalesLine.LineAmount = _dsdSalesLine.LineAmount + actAmount;
                rc+=actAmount; // no rounding here
            }
        }
        else
        {
            InventDim bomInventDim;
            select firstonly bomVersion
                where bomVersion.ItemId == inventTable.ItemId &&
                    bomVersion.Active &&
                    bomVersion.Approved
                 join bomInventDim
                 where bomInventDim.InventDimId==bomVersion.InventDimId
                 && bomInventDim.configId==_configId;
            if (bomVersion)
            {
                while select bomTable
                    where bomTable.BOMId == bomVersion.BOMId
                {
                    while select bom
                        where bom.BOMId == bomTable.BOMId
                    {                                                                   
                        EcoResItemConfigurationName bomConfigId=bom.inventDim().configId;
                        if (AVARUMDSDCalculationManager::hasInventDimCombination(bom.ItemId, bomConfigId))
                        {
                            var bomQty = (bom.BOMConsump==bomConsumpType::Constant ? bom.BOMQty : _qty * Bom.BOMQty);
                            rc+=AVARUMDSDCalculationManager::calcPackingAmount(bomQty, bom.ItemId, bomConfigId, _dsdSalesLine, _itemIdMother, _date);
                        }
                    }
                }
            }
        }
    }
    return rc;
}

/// <summary>
/// Calculates packing charges for a given item and invoice transaction, and updates or inserts the fee record.
/// </summary>
/// <param name="_configId">Item configuration ID.</param>
/// <param name="_custInvoiceTrans">Customer invoice transaction.</param>
/// <param name="_qty">Quantity to calculate for (default is 1.0).</param>
static void calcPackingCharges
(
    ItemId _itemid,
    EcoResItemConfigurationName _configId,
    CustInvoiceTrans _custInvoiceTrans,
    InventQty _qty = 1.0
)
{
    InventDimCombination inventDimCombination;
    EcoResDistinctProductVariant distinctProductVariant;
    InventTable inventTable;
    BOMVersion bomVersion;
    BOMTable bomTable;
    BOM bom;
    AVARUMDSDFeeTable fee;
    InventQty qty2;
    Real basisP;
    Real basis;
    Real basis_B;
    InventQty inventQty;
    AmountCur FeePerWeight;
    UnitIdbase unitFrom;
    UnitIdbase unitTo;
    UnitIdbase unitInvent;
    UnitOfMeasureRecId unitFromRecid;
    UnitOfMeasureRecId unittoRecid;
    UnitOfMeasureRecId unitInventrecid;
    CurrencyCode companyCurrencyCode;
    AVARUMDSDCodeTable codes;
    Currency currency;
    Boolean logModeOn = false;

    companyCurrencyCode = Ledger::accountingCurrency(CompanyInfo::current());

    InventDim locInventDim;
    locInventDim.configId=_configId;
    inventDimCombination=InventDimCombination::findByInventDim(_ItemId, locInventDim);
    distinctProductVariant=EcoResDistinctProductVariant::find(inventDimCombination.DistinctProductVariant);

    if (distinctProductVariant.AVARUMDSDUsage)
    {
        inventTable = InventTable::find(_ItemId);

        if (distinctProductVariant.AVARUMDSDPackaging)
        {
            basisP = _custInvoiceTrans.InventQty * _qty;

            if (distinctProductVariant.AVARUMDSDWeightGroupId)
            {
                fee = AVARUMDSDFeeTable::find(AVARUMDSDClass::Weight, distinctProductVariant.AVARUMDSDWeightGroupId, _custInvoiceTrans.RecId, _custInvoiceTrans.ItemId);

                if (!fee.RecId)
                {
                    fee.CodeClass = AVARUMDSDClass::Weight;
                    fee.Code = distinctProductVariant.AVARUMDSDWeightGroupId;
                    fee.InvRefId = _custInvoiceTrans.RecId;
                    fee.ItemId = _custInvoiceTrans.ItemId;
                    fee.InvoiceId = _custInvoiceTrans.InvoiceId;
                    fee.InventTransId  = _custInvoiceTrans.InventTransId;
                    fee.SalesId = _custInvoiceTrans.SalesId;
                    fee.Qty = _custInvoiceTrans.Qty;
                }
                else
                {
                    fee.selectForUpdate(true);
                }

                basis_B = basisP * distinctProductVariant.AVARUMDSDWeight; //Old: inventTable.NetWeight;
                basis = Basis_B;

                // Weight price is stored per kg
                utcDateTime unvoiceDateUtc = DateTimeUtil::newDateTime(_custInvoiceTrans.InvoiceDate, 0);
                codes = AVARUMDSDCodeTable::find(AVARUMDSDClass::Weight, distinctProductVariant.AVARUMDSDWeightGroupId, unvoiceDateUtc);
                FeePerWeight = codes.FeePerWeight;
                fee.ExactFee = basis_B * FeePerWeight;
                currency = Currency::find(companyCurrencyCode);
                fee.FeeWithOutTaxes = currency.amount_instance(fee.FeeWithOutTaxes + (basis_B * FeePerWeight));
                fee.Fee = fee.FeeWithOutTaxes;
                fee.InvoiceDate = _custInvoiceTrans.InvoiceDate;
                fee.BaseUnit = basis;

                if (!fee.RecId)
                {
                    fee.insert();
                }
                else
                {
                    fee.update();
                }

                if (logModeOn)
                {
                    Global::info(strFmt("@AVARUM:DSDNewRecord", fee.RecId, fee.FeeWithOutTaxes, fee.Fee, fee.BaseUnit, fee.InvoiceDate));
                }
            }
        }
        else
        {                 
            InventDim bomInventDim;
            select firstonly bomVersion
                where bomVersion.ItemId == inventTable.ItemId && bomVersion.Active && bomVersion.Approved
                join bomInventDim
                where bomInventDim.InventDimId==bomVersion.InventDimId
                && bomInventDim.configId==_configId;
            if (bomVersion)
            {
                while select bomTable
                        where bomTable.BOMId == bomVersion.BOMId
                {
                    while select bom
                            where bom.BOMId == bomTable.BOMId 
                    {                                         
                        EcoResItemConfigurationName bomConfigId=bom.inventDim().configId;
                        if (AVARUMDSDCalculationManager::hasInventDimCombination(bom.ItemId, bomConfigId))
                        {
                            var bomQty = (bom.BOMConsump==bomConsumpType::Constant ? bom.BOMQty : _qty * bom.BOMQty);
                            AVARUMDSDCalculationManager::calcPackingCharges(bom.ItemId, bomConfigId, _custInvoiceTrans, bomQty);
                        }
                    }
                }
            }
        }
    }
}

/// <summary>
/// Main entry point for recalculating existing packing charges.
/// </summary>
/// <param name="args">Arguments.</param>
static void main(Args args)
{
    AVARUMDSDCalculationManager::reCalcExistingPackingCharges();
}

/// <summary>
/// Recalculates existing packing charges for invoice transactions within a date range.
/// </summary>
/// <param name="_fromDate">Start date (default is null).</param>
/// <param name="_toDate">End date (default is today).</param>
static void reCalcExistingPackingCharges(TransDate _fromDate = Global::datenull(), TransDate _toDate = today())
{
    EcoResDistinctProductVariant distinctProductVariant;
    InventTable inventTable;
    CustInvoiceTrans custInvoiceTrans;
    AVARUMDSDFeeTable feeTable;
    Boolean deleted;
    Int counter;
    Int innerCounter;
    AVARUMDSDParameters parameter;
    Boolean logModeOn;
    Boolean feeFound;

    parameter = AVARUMDSDParameters::find();

    while select distinctProductVariant
            where distinctProductVariant.AVARUMDSDUsage == NoYes::Yes
        join inventTable
            where inventTable.Product == distinctProductVariant.ProductMaster
    {
        while select custInvoiceTrans
            where custInvoiceTrans.ItemId == inventTable.ItemId && custInvoiceTrans.InvoiceDate >= _fromDate && custInvoiceTrans.InvoiceDate <= _toDate
        {
            ttsbegin;

            deleted = false;
            feeFound = false;
            innerCounter = 0;

            boolean hasVariant=AVARUMDSDCalculationManager::hasInventDimCombination(custInvoiceTrans. ItemId, custInvoiceTrans.inventDim().ConfigId);                

            while select forupdate feeTable
                where feeTable.InvRefId == custInvoiceTrans.RecId || feeTable.InventTransId  == custInvoiceTrans.InventTransId // && feeTable.Entered == NoYes::No
            {
                deleted = true;
                feeFound = true;
                innerCounter++;
                counter++;

                if (custInvoiceTrans.InvoiceDate >= 1\1\2009 && custInvoiceTrans.InvoiceDate <= 1\02\2009)
                {
                    print '';
                }

                if(logModeOn)
                {
                    Global::info(strFmt("@AVARUM:DSDOldRecord",
                    feeTable.RecId, feeTable.FeeWithOutTaxes, feeTable.Fee, feeTable.BaseUnit, feeTable.InvoiceDate, counter));
                }

                feeTable.delete();

                if (innerCounter > 1 && logModeOn)
                {
                    Global::warning(strFmt("@AVARUM:DSDDuplicateRecord", custInvoiceTrans.InvoiceId));
                }

                if (deleted)
                {
                    if (hasVariant)
                    {
                        AVARUMDSDCalculationManager::calcPackingCharges(custInvoiceTrans.ItemId,  custInvoiceTrans.inventDim().ConfigId, custInvoiceTrans, 1.0);
                    }
                }
                else
                {
                    Global::info(strfmt("@AVARUM:DSDNotUpdatedRecord", feeTable.RecId));
                }
            }

            if (!feeFound)
            {
                AVARUMDSDCalculationManager::calcPackingCharges(custInvoiceTrans.ItemId, custInvoiceTrans.inventDim().ConfigId, custInvoiceTrans, 1.0);
            }

            ttscommit;
        }
    }

    print counter;
}

/// <summary>
/// Recalculates packing charges for invoice transactions from a fixed date onward.
/// </summary>
static void reCalcPackingCharges()
{
    EcoResDistinctProductVariant distinctProductVariant;
    InventTable inventTable;
    CustInvoiceTrans custInvoiceTrans;
    AVARUMDSDFeeTable feeTable;
    Boolean deleted;
    Int counter;
    Int innerCounter;
    AVARUMDSDParameters parameter;

    parameter = AVARUMDSDParameters::find();

    while select distinctProductVariant
            where distinctProductVariant.AVARUMDSDUsage == NoYes::Yes                
        join inventTable
            where inventTable.Product == distinctProductVariant.ProductMaster
    {                 
        while select custInvoiceTrans
            where custInvoiceTrans.ItemId == inventTable.ItemId && custInvoiceTrans.InvoiceDate >= 01\07\2010
        {
            ttsbegin;
            deleted = false;
            innerCounter = 0;

            while select forupdate feeTable
                where feeTable.InvRefId == custInvoiceTrans.RecId || feeTable.InventTransId  == custInvoiceTrans.InventTransId //&& GP_Abgabe.Gebucht == NoYes::No
            {
                counter ++;
                innerCounter ++;
                deleted = true;

                Global::info
                (
                    strFmt
                    (
                        "@AVARUM:DSDOldRecord",
                        feeTable.RecId, 
                        feeTable.FeeWithOutTaxes, 
                        feeTable.Fee, 
                        feeTable.BaseUnit, 
                        feeTable.InvoiceDate, 
                        counter
                    )
                );

                if(innerCounter > 1)
                {
                    Global::info(strFmt("@AVARUM:DSDDuplicateRecord", custInvoiceTrans.InvoiceId));
                }
            }

            if (deleted)
            {                    

                if (AVARUMDSDCalculationManager::hasInventDimCombination(custInvoiceTrans.ItemId, custInvoiceTrans.inventDim().ConfigId))
                {
                    AVARUMDSDCalculationManager::calcPackingCharges(custInvoiceTrans.ItemId, custInvoiceTrans.inventDim().ConfigId, custInvoiceTrans, 1.0);
                }
            }
            else
            {
                Global::info(strfmt( "@AVARUM:DSDNotUpdatedRecord", feeTable.RecId));
            }

            ttscommit;
        }
    }
}

/// <summary>
/// Checks the combination  based on item and configuration IDs.
/// </summary>
/// <param name = "_itemid">The ID of the item to validate</param>
/// <param name = "_configId">The configuration ID of the item.</param>
/// <returns>True if combination is guilty</returns>
private static boolean hasInventDimCombination(ItemId _itemid, EcoResItemConfigurationName _configId)
{
    InventDim inventDim;
    InventDimCombination inventDimCombination;

    select firstonly inventDimCombination
        exists join inventDim
        where inventDim.InventDimId == inventDimCombination.InventDimId &&
            inventDimCombination.ItemId == _itemid &&
            inventDim.ConfigId == _configId;

    return (inventDimCombination.RecId!=0);

}
